SELECT p.name, p.category, p.tier_slug, p.billing_cycle, p.unit_price, p.price_ghs, bu.name AS business_unit_name FROM public.crm_products p LEFT JOIN public.business_units bu ON bu.id = p.business_unit_id WHERE p.tenant_id = '00000001-0000-4000-8000-000000000001' AND ((p.category = 'ERP Suite' AND p.tier_slug IS NOT NULL) OR p.category = 'Platform Billing' OR p.name LIKE 'SMS Credits — %') ORDER BY p.category, p.tier_slug NULLS LAST, p.billing_cycle, p.name;
